UPDATE adi_index_task
SET status      = CASE WHEN status = 'pending' THEN 'failed' ELSE status END,
    fail_reason = CASE WHEN status = 'pending' THEN 'superseded by newer version' ELSE fail_reason END,
    stop_flag   = true,
    update_time = now()
WHERE doc_uuid = #{task.docUuid}
  AND segment_uuid = #{task.segmentUuid}
  AND target_type = #{task.targetType}
  AND task_type = #{task.taskType}
  AND index_version < #{task.indexVersion}
  AND status IN ('pending', 'running')
